const SEND_WINDOW_MINUTES = 60;
const FALLBACK_TIME_ZONE = 'Europe/Paris';

function getUser(item) {
  return item.json;
}

function getTimeZone(user) {
  if (user.timezone && DateTime.now().setZone(user.timezone).isValid) {
    return user.timezone;
  }
  return FALLBACK_TIME_ZONE;
}

function isSendTime(user, nowForUser) {
  const sendTime = DateTime.fromFormat(user.send_hour || '', 'H:mm');
  if (!sendTime.isValid) {
    return false;
  }
  const windowStart = nowForUser.set({ hour: sendTime.hour, minute: sendTime.minute, second: 0, millisecond: 0 });
  const windowEnd = windowStart.plus({ minutes: SEND_WINDOW_MINUTES });
  return nowForUser >= windowStart && nowForUser < windowEnd;
}

function wasServedToday(user, nowForUser) {
  if (!user.last_sent) {
    return false;
  }
  const lastSentForUser = DateTime.fromISO(user.last_sent).setZone(nowForUser.zone);
  return lastSentForUser.hasSame(nowForUser, 'day');
}

function isDue(user) {
  const nowForUser = DateTime.now().setZone(getTimeZone(user));
  return isSendTime(user, nowForUser) && !wasServedToday(user, nowForUser);
}

function toSendRequest(user) {
  return { json: { user_id: user.id } };
}

return $input.all().map(getUser).filter(isDue).map(toSendRequest);

function createEmptySummary(dueCount) {
  return { due: dueCount, sent: 0, no_new_articles: 0, failed: 0, failures: [] };
}

function getUserId(item) {
  const dueIndex = item.pairedItem?.item;
  return item.json.user_id ?? dueUsers[dueIndex]?.json.user_id ?? null;
}

function toFailure(item) {
  return { user_id: getUserId(item), reason: item.json.reason || 'error', error: item.json.error || null };
}

function addToSummary(summary, item) {
  if (item.json.sent) {
    summary.sent++;
  } else if (item.json.reason === 'no_matching_articles') {
    summary.no_new_articles++;
  } else {
    summary.failed++;
    summary.failures.push(toFailure(item));
  }
  return summary;
}

const dueUsers = $('Due now').all();
const summary = $input.all().reduce(addToSummary, createEmptySummary(dueUsers.length));

return [{ json: summary }];
